import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterStatus,
} from 'hooks';

import {
  PHI_OVERVIEW_PHI_OVERTIME_SUBTITLE_I18N_ID,
  PORTFOLIO_HEALTH_INDEX_PAGE_NAME,
} from '../../constants';
import {
  getPhiChartLegendItems,
  getPhiCountryScope,
  getPhiScopeSectionTitle,
} from '../../utils';
import { PHI_OVERVIEW_MOCK_ONLY } from './constants';
import { usePhiOverviewSectionData, usePhiOverviewSectionUi } from './hooks';
import { StyledOverviewRoot } from './Overview.styles';
import {
  PhiPerformanceOverviewSection,
  resolveOverviewTestId,
  TotalPhiOverviewSection,
} from './OverviewSections';

export interface OverviewProps {
  countryScope?: string;
  dataTestId?: string;
}

export const Overview: React.FC<OverviewProps> = ({
  countryScope: countryScopeProp,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { applied, isGlobalZone } = usePageFilterApplied(
    PORTFOLIO_HEALTH_INDEX_PAGE_NAME,
  );
  const { dataFilters } = usePageFilterData(PORTFOLIO_HEALTH_INDEX_PAGE_NAME);
  const { isError: filtersLoadError } = usePageFilterStatus(
    PORTFOLIO_HEALTH_INDEX_PAGE_NAME,
  );
  const filtersError = PHI_OVERVIEW_MOCK_ONLY ? false : filtersLoadError;

  const { view: totalPhiView, data: totalPhiData } =
    usePhiOverviewSectionData('totalPhi');
  const { view: phiPerformanceView, data: phiPerformanceData } =
    usePhiOverviewSectionData('phiPerformance');
  const { view: beerEvolutionView, data: beerEvolutionData } =
    usePhiOverviewSectionData('beerEvolutionBreakdown');
  const { stateMessage: totalPhiStateMessage } =
    usePhiOverviewSectionUi(totalPhiView);
  const { stateMessage: phiPerformanceStateMessage } =
    usePhiOverviewSectionUi(phiPerformanceView);
  const { stateMessage: beerEvolutionStateMessage } =
    usePhiOverviewSectionUi(beerEvolutionView);

  const countryScope = useMemo(() => {
    if (countryScopeProp !== undefined) {
      return countryScopeProp;
    }

    return getPhiCountryScope(dataFilters, applied, isGlobalZone);
  }, [applied, countryScopeProp, dataFilters, isGlobalZone]);

  const overtime = phiPerformanceData?.overtime;

  const totalPhiTitle = useMemo(
    () => getPhiScopeSectionTitle(formatMessage, 'totalPhi', countryScope),
    [countryScope, formatMessage],
  );

  const phiPerformanceTitle = useMemo(
    () =>
      getPhiScopeSectionTitle(formatMessage, 'phiPerformance', countryScope),
    [countryScope, formatMessage],
  );

  const chartLegendItems = useMemo(
    () =>
      getPhiChartLegendItems(
        overtime?.lineChart.datasets.map((dataset) => dataset.label ?? '') ??
          [],
      ),
    [overtime?.lineChart.datasets],
  );

  const overtimeSubtitle = formatMessage({
    id: PHI_OVERVIEW_PHI_OVERTIME_SUBTITLE_I18N_ID,
  });

  return (
    <StyledOverviewRoot
      data-testid={resolveOverviewTestId(
        dataTestId,
        'container',
        'portfolio-health-index-overview-container',
      )}
    >
      <TotalPhiOverviewSection
        title={totalPhiTitle}
        dataTestId={dataTestId}
        view={totalPhiView}
        data={totalPhiData}
        stateMessage={totalPhiStateMessage}
      />
      <PhiPerformanceOverviewSection
        title={phiPerformanceTitle}
        overtimeSubtitle={overtimeSubtitle}
        dataTestId={dataTestId}
        view={phiPerformanceView}
        overtime={overtime}
        stateMessage={phiPerformanceStateMessage}
        chartLegendItems={chartLegendItems}
        filtersError={filtersError}
        beerEvolution={{
          data: beerEvolutionData,
          view: beerEvolutionView,
          stateMessage: beerEvolutionStateMessage,
          dataTestId: resolveOverviewTestId(
            dataTestId,
            'beer-evolution',
            'beer-evolution-breakdown-section',
          ),
        }}
      />
    </StyledOverviewRoot>
  );
};
